package com.buildalot.game

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class BuildalotTest {

    @Test fun starts_broke_but_hopeful() {
        val g = Game()
        assertEquals(START_CASH, g.cash)
        assertEquals(1, g.turn)
        assertTrue(g.plots.none { it.owned })
        assertEquals(0, g.netWorth() - START_CASH)
    }

    @Test fun buying_a_plot_costs_cash_and_marks_it_owned() {
        val g = Game()
        assertTrue(g.buyPlot(0))
        assertTrue(g.plots[0].owned)
        assertEquals(START_CASH - PLOT_PRICE, g.cash)
    }

    @Test fun cannot_buy_the_same_plot_twice() {
        val g = Game()
        g.buyPlot(2)
        val cashAfterFirst = g.cash
        assertFalse(g.buyPlot(2))
        assertEquals(cashAfterFirst, g.cash)
    }

    @Test fun cannot_buy_what_you_cannot_afford() {
        val g = Game()
        repeat(PLOTS) { g.buyPlot(it) }          // spends 6 * 2000 = 12000, leaves 3000
        // now try to build+upgrade past the cash on hand
        assertTrue(g.build(0))                    // -3000 -> 0 left
        assertFalse(g.build(1))                   // can't afford another
        assertNull(g.plots[1].house)
    }

    @Test fun cannot_build_on_a_plot_you_do_not_own() {
        val g = Game()
        assertFalse(g.build(0))
        assertNull(g.plots[0].house)
    }

    @Test fun a_new_house_is_not_finished_yet() {
        val g = Game()
        g.buyPlot(0)
        assertTrue(g.build(0))
        assertEquals(START_CASH - PLOT_PRICE - BUILD_COST, g.cash)
        assertFalse(g.plots[0].house!!.finished)
    }

    @Test fun a_house_finishes_after_build_turns() {
        val g = Game()
        g.buyPlot(0); g.build(0)
        repeat(BUILD_TURNS) { g.endTurn() }
        assertTrue(g.plots[0].house!!.finished)
        assertEquals(1 + BUILD_TURNS, g.turn)
    }

    @Test fun only_finished_houses_earn_rent() {
        val g = Game()
        g.buyPlot(0); g.build(0)
        val beforeAnyRent = g.cash
        g.endTurn()                               // house still has 1 turn left -> no rent
        assertEquals(beforeAnyRent, g.cash)
        g.endTurn()                               // finishes this turn -> still no rent this turn
        val afterFinish = g.cash
        g.endTurn()                               // now it's finished -> one rent payment
        assertEquals(afterFinish + RENT_PER_LEVEL * 1, g.cash)
    }

    @Test fun upgrading_raises_level_costs_money_and_caps_at_max() {
        val g = Game()
        g.buyPlot(0); g.build(0)
        repeat(BUILD_TURNS) { g.endTurn() }       // finished, level 1
        val cash0 = g.cash
        assertTrue(g.upgrade(0))
        assertEquals(2, g.plots[0].house!!.level)
        assertEquals(cash0 - UPGRADE_COST * 1, g.cash)
        assertTrue(g.upgrade(0))                  // -> level 3
        assertFalse(g.upgrade(0))                 // capped
        assertEquals(MAX_LEVEL, g.plots[0].house!!.level)
    }

    @Test fun selling_frees_the_plot_and_returns_money() {
        val g = Game()
        g.buyPlot(0); g.build(0)
        repeat(BUILD_TURNS) { g.endTurn() }
        val cashBefore = g.cash
        val expected = cashBefore + PLOT_PRICE / 2 + g.houseValue(0)
        assertTrue(g.sell(0))
        assertFalse(g.plots[0].owned)
        assertNull(g.plots[0].house)
        assertEquals(expected, g.cash)
    }

    @Test fun house_value_reflects_upgrades() {
        val g = Game()
        g.buyPlot(0); g.build(0)
        repeat(BUILD_TURNS) { g.endTurn() }
        assertEquals(BUILD_COST, g.houseValue(0))
        g.upgrade(0)
        assertEquals(BUILD_COST + UPGRADE_COST, g.houseValue(0))
    }

    @Test fun net_worth_counts_cash_plots_and_houses() {
        val g = Game()
        g.buyPlot(0)
        g.buyPlot(1); g.build(1)
        val expected = g.cash + (PLOT_PRICE / 2) + (PLOT_PRICE / 2 + g.houseValue(1))
        assertEquals(expected, g.netWorth())
    }

    @Test fun you_win_at_the_target() {
        val g = Game()
        assertFalse(g.hasWon())
        // buy a plot, build, max it, then sit collecting rent for a long while
        g.buyPlot(0); g.build(0)
        repeat(BUILD_TURNS) { g.endTurn() }
        g.upgrade(0); g.upgrade(0)               // level 3
        repeat(60) { g.endTurn() }               // 60 * 1500 rent = 90k
        assertTrue(g.hasWon())
    }
}

