            plot.house!!.turnsLeft--
            if (plot.house!!.finished) {
                cash += plot.house!!.level * RENT_PER_LEVEL
            }
        }
    }
}

    /** What a plot's house is worth: 0 if none, otherwise BUILD_COST plus
     *  UPGRADE_COST * (level - 1) for the upgrades put into it. An
     *  unfinished house still counts at its current level. */
fun houseValue(i: Int): Int {
    if (i < 0 || i >= plots.size || plots[i].house == null) {
        return 0
    }
    val house = plots[i].house!!
    return BUILD_COST + UPGRADE_COST * (house.level - 1)
}

    /** cash + for every owned plot: half of PLOT_PRICE + houseValue(i). */
fun netWorth(): Int {
    var netWorth = cash
    for (plot in plots) {
        if (plot.owned) {
            netWorth += PLOT_PRICE / 2
            if (plot.house != null) {
                netWorth += plot.house!!.level * UPGRADE_COST
            }
        }
    }
    return netWorth
}

    fun hasWon(): Boolean = netWorth() >= TARGET_NET_WORTH
}
